import 'dotenv/config';
import path from 'path';
import { defineConfig } from 'prisma/config';

// The Prisma CLI resolves a relative `sslcert` from this folder, while the
// app (prisma.ts) resolves it from prisma/. Make it absolute under prisma/
// so `sslcert=./ca.pem` means prisma/ca.pem for both.
function resolveSslCert(url: string | undefined) {
   if (!url) return url;
   const parsed = new URL(url);
   const sslcert = parsed.searchParams.get('sslcert');
   if (!sslcert || path.isAbsolute(sslcert)) return url;
   parsed.searchParams.set(
      'sslcert',
      path.resolve(import.meta.dirname, 'prisma', sslcert)
   );
   return parsed.toString();
}

export default defineConfig({
   schema: 'prisma/schema.prisma',
   migrations: {
      path: 'prisma/migrations',
      seed: 'bun prisma/seed.ts',
   },
   datasource: {
      url: resolveSslCert(process.env['DATABASE_URL']),
   },
});
